def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_c = my_d = opp_c = opp_d = 0
    for a, b in history:
        if a == 'C':
            my_c += 1
        else:
            my_d += 1
        if b == 'C':
            opp_c += 1
        else:
            opp_d += 1

    if n < 4:
        return 'C'

    last_my, last_opp = history[-1]

    # Count consecutive opponent defections at the end.
    consec_opp_d = 0
    for a, b in reversed(history):
        if b == 'D':
            consec_opp_d += 1
        else:
            break

    # Count consecutive opponent cooperations at the end.
    consec_opp_c = 0
    for a, b in reversed(history):
        if b == 'C':
            consec_opp_c += 1
        else:
            break

    recent = history[-12:] if n >= 12 else history
    r_op_c = sum(1 for a, b in recent if b == 'C')
    r_my_d = sum(1 for a, b in recent if a == 'D')
    r_len = len(recent)

    # Windowed cooperation rates.
    w5 = history[-5:]
    w5_opp_c = sum(1 for a, b in w5 if b == 'C')
    w10 = history[-10:]
    w10_opp_c = sum(1 for a, b in w10 if b == 'C')

    opp_coop = opp_c / n
    my_coop = my_c / n

    # Detect punishing opponents: they defected after our defection.
    punish_after_my_d = 0
    exploit_after_my_d = 0
    my_d_total_seen = 0
    for i in range(1, n):
        if history[i - 1][0] == 'D':
            my_d_total_seen += 1
            if history[i][1] == 'D':
                punish_after_my_d += 1
            else:
                exploit_after_my_d += 1

    # Detect forgiving opponents: they cooperated after our defection.
    forgive_rate = 1.0
    if my_d_total_seen > 0:
        forgive_rate = exploit_after_my_d / float(my_d_total_seen)

    # Detect always-defect / near always-defect.
    if n >= 6 and opp_d >= n - 1:
        return 'D'
    if n >= 10 and opp_coop <= 0.1:
        return 'D'

    # Detect always-cooperate / near always-cooperate.
    if n >= 6 and opp_d == 0:
        if n >= 12 and my_d == 0:
            return 'D'
        return 'C'

    remaining = 100 - n

    # Endgame: exploit persistent cooperators, but be careful against punishers.
    if remaining <= 2:
        if opp_d == 0:
            return 'D'
        if last_opp == 'D' or consec_opp_d >= 2:
            return 'D'
        if forgive_rate >= 0.5 and opp_coop >= 0.5:
            return 'D'
        if last_opp == 'C' and opp_coop >= 0.7:
            return 'D'
        return 'C'

    if remaining <= 5:
        if opp_d == 0:
            return 'D'
        if opp_coop >= 0.6 and forgive_rate >= 0.4:
            return 'D'
        if last_opp == 'D' and opp_coop >= 0.4:
            return 'D'
        if consec_opp_c >= 2 and opp_coop >= 0.7:
            return 'D'
        return 'C'

    # Endgame against very cooperative opponent: start probing earlier.
    if remaining <= 12 and opp_coop >= 0.8:
        if last_opp == 'C' and rng.random() < 0.5:
            return 'D'
        return 'C'

    # If opponent defects often, defect but probe occasionally.
    if opp_coop < 0.3:
        if last_opp == 'D':
            if n % 7 == 0:
                return 'C'
            return 'D'
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    # Persistent defection run: retaliate hard briefly, then test cooperation.
    if consec_opp_d >= 3:
        if rng.random() < 0.12:
            return 'C'
        return 'D'

    # Opponent defected last move.
    if last_opp == 'D':
        # If opponent is mostly cooperative, forgive quickly to restore CC.
        if opp_coop >= 0.7 and consec_opp_d <= 2:
            if forgive_rate >= 0.3 or consec_opp_d == 1:
                return 'C'
        # If overall cooperation moderate and disruption is small, forgive.
        if opp_coop >= 0.5 and consec_opp_c >= 1 and consec_opp_d == 1:
            return 'C'
        # If our last move was D and opponent retaliated once, return to C
        # to break the DD spiral unless they have shown persistent punishment.
        if last_my == 'D' and consec_opp_d == 1:
            if punish_after_my_d <= 1 and opp_coop >= 0.45:
                return 'C'
        # Otherwise retaliate.
        return 'D'

    # Opponent cooperated last move.
    # If opponent nearly always cooperates, exploit occasionally.
    if opp_coop >= 0.9 and n >= 10:
        if n % 9 == 0 and opp_d == 0:
            return 'D'
        return 'C'

    if opp_coop >= 0.8 and n >= 12:
        if r_my_d == 0 and rng.random() < 0.08:
            return 'D'
        return 'C'

    # If we defected last and opponent still cooperated, exploit a bit
    # only if they are forgiving and we haven't overdone it.
    if last_my == 'D' and forgive_rate >= 0.5 and my_d < 6 and remaining > 15:
        if rng.random() < 0.35:
            return 'D'

    # If mutual cooperation has been stable, preserve it.
    if consec_opp_c >= 3 and opp_coop >= 0.6:
        return 'C'

    if w5_opp_c >= 4:
        return 'C'
    if w10_opp_c * 2 >= len(w10):
        return 'C'

    # Moderate opponent cooperation: cooperate, but retaliate if they defect.
    if opp_coop >= 0.4:
        return 'C'

    # Low-ish cooperation but opponent just cooperated: give cooperation a chance.
    if last_opp == 'C':
        return 'C'

    return 'D'
